// ============================================
// FAQ SCHEMA HELPER (JSON-LD FAQPage for SEO)
// ============================================

function truncate(str, max) {
  if (!str) return '';
  str = String(str).replace(/\s+/g, ' ').trim();
  return str.length <= max ? str : str.slice(0, max - 3) + '...';
}

function buildReviewFaqSchema(r) {
  const title = r.title || 'This title';
  const year = r.year ? ` (${r.year})` : '';
  const verdict = r.verdict || 'MIXED';
  const scoreMargin = r.scoreMargin || 'N/A';
  const tradScore = r.tradScore != null ? r.tradScore : 'N/A';
  const wokeScore = r.wokeScore != null ? r.wokeScore : 'N/A';

  // Q1: Is it woke?
  const summarySnippet = r.summary && r.summary.overall
    ? truncate(r.summary.overall.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' '), 120)
    : '';
  const a1 = truncate(
    `${verdict} -- ${title} scores ${scoreMargin} on the VirtueVigil VVWS scale.` +
    (summarySnippet ? ` ${summarySnippet}` : ''),
    300
  );

  // Q2: VirtueVigil score
  const a2 = truncate(
    `VirtueVigil scores ${title} as ${verdict} with a margin of ${scoreMargin}. Traditional score: ${tradScore}, Woke score: ${wokeScore}.`,
    300
  );

  // Q3: Safe for kids -- use summary.parentalGuidance if available
  let a3;
  if (r.summary && r.summary.parentalGuidance) {
    a3 = truncate(r.summary.parentalGuidance.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' '), 300);
  } else {
    const vUpper = verdict.toUpperCase();
    if (vUpper.includes('STRONGLY TRADITIONAL') || vUpper.includes('STRONGLY TRAD')) {
      a3 = `${title} is rated ${verdict} -- generally safe for families and children with traditional values.`;
    } else if (vUpper === 'TRADITIONAL' || vUpper === 'TRAD') {
      a3 = `${title} scores TRADITIONAL on VirtueVigil. Generally appropriate for family viewing. Check the full review for content details.`;
    } else if (vUpper.includes('LEAN')) {
      a3 = `${title} leans traditional but contains some content parents should review before watching with younger children.`;
    } else if (vUpper === 'MIXED') {
      a3 = `${title} scored MIXED on VirtueVigil. Parental discretion advised -- review the full analysis for specific content flags.`;
    } else if (vUpper.includes('WOKE TRAP')) {
      a3 = `${title} is flagged as a WOKE TRAP -- content is more progressive than marketing suggests. Caution for families.`;
    } else if (vUpper.includes('STRONGLY WOKE')) {
      a3 = `${title} scored STRONGLY WOKE. Not recommended for conservative families. Contains heavy progressive messaging.`;
    } else if (vUpper.includes('WOKE')) {
      a3 = `${title} scored WOKE on VirtueVigil. Contains progressive content -- not recommended for conservative family viewing.`;
    } else {
      a3 = `See the full VirtueVigil review of ${title} for a complete parental guidance assessment.`;
    }
    a3 = truncate(a3, 300);
  }

  // Q4: Woke tropes -- handle both array (VVWS) and object ({woke_tropes, traditional_tropes}) formats
  let a4;
  let wokeTropes = [];
  const ta = r.tropeAudit;
  if (Array.isArray(ta)) {
    wokeTropes = ta
      .filter(t => (t.category || '').toLowerCase() === 'woke')
      .slice(0, 3)
      .map(t => t.name);
  } else if (ta && Array.isArray(ta.woke_tropes)) {
    wokeTropes = ta.woke_tropes.slice(0, 3).map(t => t.name);
  }
  if (wokeTropes.length > 0) {
    a4 = truncate(`Woke content identified in ${title}: ${wokeTropes.join('; ')}.`, 300);
  } else {
    a4 = `No significant woke content identified in ${title} by VirtueVigil's trope audit.`;
  }

  // Q5: Would conservatives enjoy it?
  let a5;
  const vUpper = verdict.toUpperCase();
  if (vUpper.includes('STRONGLY TRADITIONAL') || vUpper.includes('STRONGLY TRAD')) {
    a5 = truncate(`Yes -- conservatives will thoroughly enjoy ${title}. It scores ${verdict} and strongly affirms traditional values.`, 300);
  } else if (vUpper === 'TRADITIONAL' || vUpper === 'TRAD') {
    a5 = truncate(`Yes -- ${title} scores TRADITIONAL on VirtueVigil. Conservatives should find it worth watching.`, 300);
  } else if (vUpper.includes('LEAN')) {
    a5 = truncate(`Probably -- ${title} leans traditional with minor progressive elements. Most conservatives will enjoy it with minor caveats.`, 300);
  } else if (vUpper === 'MIXED') {
    a5 = truncate(`Mixed bag -- ${title} has both traditional and progressive elements. Conservative viewers may enjoy parts but should read the full review first.`, 300);
  } else if (vUpper.includes('STRONGLY WOKE')) {
    a5 = truncate(`No -- ${title} scored STRONGLY WOKE on VirtueVigil. Heavy progressive messaging throughout.`, 300);
  } else if (vUpper.includes('WOKE')) {
    a5 = truncate(`Unlikely -- ${title} scored WOKE on VirtueVigil. Contains significant progressive content most conservatives will find objectionable.`, 300);
  } else {
    a5 = truncate(`See the full VirtueVigil review of ${title} for a conservative viewer recommendation.`, 300);
  }

  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": `Is ${title}${year} woke?`,
        "acceptedAnswer": { "@type": "Answer", "text": a1 }
      },
      {
        "@type": "Question",
        "name": `What is the VirtueVigil score for ${title}?`,
        "acceptedAnswer": { "@type": "Answer", "text": a2 }
      },
      {
        "@type": "Question",
        "name": `Is ${title} safe for kids?`,
        "acceptedAnswer": { "@type": "Answer", "text": a3 }
      },
      {
        "@type": "Question",
        "name": `What woke content appears in ${title}?`,
        "acceptedAnswer": { "@type": "Answer", "text": a4 }
      },
      {
        "@type": "Question",
        "name": `Would conservatives enjoy ${title}?`,
        "acceptedAnswer": { "@type": "Answer", "text": a5 }
      }
    ]
  };
}

// Related reviews: same genre bucket, same verdict tier, exclude self. Max 8.
function getRelatedReviews(r) {
  const myGenres = classifyGenreNav(r.genre);
  const myVerdict = (r.verdict || '').toUpperCase();
  const scored = reviews
    .filter(other => other.slug !== r.slug)
    .map(other => {
      let score = 0;
      const otherGenres = classifyGenreNav(other.genre);
      const sharedGenres = myGenres.filter(g => otherGenres.includes(g));
      score += sharedGenres.length * 3;
      const ov = (other.verdict || '').toUpperCase();
      if (ov === myVerdict) score += 2;
      else if (ov.includes('TRADITIONAL') && myVerdict.includes('TRADITIONAL')) score += 1;
      else if (ov.includes('WOKE') && myVerdict.includes('WOKE')) score += 1;
      if (other.type === r.type) score += 1;
      return { review: other, score };
    })
    .filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 8)
    .map(s => s.review);
  return scored;
}

function relatedReviewsBlock(r) {
  const related = getRelatedReviews(r);
  if (related.length === 0) return '';
  return `
      <section class="related-reviews" style="margin: 2rem 0; padding: 1.5rem; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px;">
        <h3 style="margin: 0 0 1rem 0; font-size: 1.1rem; color: var(--accent, #e2b55a);">
          <i class="fas fa-film" style="margin-right: 0.5rem;"></i>Related Reviews
        </h3>
        <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 0.75rem;">
          ${related.map(rel => {
            const relVc = verdictClass(rel.verdict);
            const badge = (rel.verdict || 'MIXED').toUpperCase();
            return `<a href="/reviews/${rel.slug}/" style="text-decoration:none; display:flex; flex-direction:column; gap:0.25rem; padding:0.5rem; border-radius:8px; background:rgba(255,255,255,0.03); transition:background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.08)'" onmouseout="this.style.background='rgba(255,255,255,0.03)'">
              ${posterHTML(rel, 'thumb')}
              <span style="font-size:0.8rem; font-weight:600; color:#eee; line-height:1.2;">${esc(rel.title)}</span>
              <span class="verdict verdict-badge ${relVc}" style="font-size:0.6rem; padding:1px 4px; align-self:flex-start;">${badge}</span>
            </a>`;
          }).join('')}
        </div>
      </section>`;
}

function buildReviewPage(r) {
  const vc = verdictClass(r.verdict);
  const hasTrap = isWokeTrap(r);
  const seo = r.seo || {};
  const title = seo.titleTag || `Is ${r.title} Woke? | VirtueVigil`;
  const desc = seo.metaDescription || `VirtueVigil review of ${r.title}. Woke Score ${r.wokeScore}, Traditional ${r.tradScore}.`;
  const kw = seo.keywords || '';
  const canonical = `${SITE_URL}/reviews/${r.slug}/`;
  const ogImage = r.poster
    ? (r.poster.startsWith('http') ? r.poster : `${SITE_URL}${r.poster}`)
    : undefined;

  const structuredData = {
    "@context": "https://schema.org",
    "@type": "Review",
    "name": r.title,
    "author": { "@type": "Person", "name": r.author },
    "datePublished": r.date,
    "reviewBody": plainText(r.summary.overall, 500),
    "publisher": { "@type": "Organization", "name": "VirtueVigil" },
    "itemReviewed": Object.assign({
      "@type": r.type === 'film' ? "Movie" : "TVSeries",
      "name": r.title,
      "datePublished": String(r.year)
    }, ogImage ? { "image": ogImage } : {}),
    "reviewRating": {
      "@type": "Rating",
      "ratingValue": r.authIndex != null ? r.authIndex : 0,
      "bestRating": 100,
      "worstRating": 0
    }
  };

  // Previous / Next navigation
  const idx = reviews.findIndex(rv => rv.id === r.id);
  const prev = idx < reviews.length - 1 ? reviews[idx + 1] : null;
  const next = idx > 0 ? reviews[idx - 1] : null;

  const reviewBreadcrumbs = breadcrumbLD([
    { name: 'Home', url: SITE_URL },
    { name: 'Reviews', url: `${SITE_URL}/reviews/` },
    { name: r.title, url: canonical }
  ]);

  const faqSchema = buildReviewFaqSchema(r);

  return `${htmlHead({ title, description: desc, keywords: kw, canonical, ogType: 'article', ogImage, structuredData, breadcrumbs: reviewBreadcrumbs, faqSchema, extraHead: '<style>.review-detail::before{display:none!important;content:none!important;}</style>' })}
<body>
  ${topBanner()}
  ${siteHeader('index')}

  <div class="page-layout">
    ${sidebarHTML()}

    <main class="main-content" role="main">
      <nav class="breadcrumb" aria-label="Breadcrumb">
        <a href="/">Home</a> <span>&rsaquo;</span>
        <a href="/">Reviews</a> <span>&rsaquo;</span>
        <span>${esc(r.title)}</span>
      </nav>

      <article class="featured-review review-detail" style="position:relative;" itemscope itemtype="https://schema.org/Review">
        <div class="featured-header">
          <div class="featured-header-layout" style="display:flex;gap:28px;align-items:flex-start;">
            <div class="featured-header-text" style="flex:1;min-width:0;">
              <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;flex-wrap:wrap;">
                <span class="verdict-badge ${vc}"><i class="fas fa-${verdictIcon(vc)}"></i> ${esc(r.verdict)}</span>
                ${hasTrap ? '<span class="verdict-badge trap"><i class="fas fa-eye-slash"></i> WOKE TRAP DETECTED</span>' : ''}
              </div>
              <h1 class="review-title" itemprop="name">${esc(r.title)}</h1>
              <p class="review-subtitle" itemprop="description">${esc(firstParagraph(r.summary.overall, 300))}</p>
              <a href="#review-body" class="review-scroll-cue"><i class="fas fa-chevron-down"></i> Full analysis below</a>
              <div class="featured-meta">
                <span><i class="fas fa-${r.type === 'film' ? 'film' : 'tv'}"></i> ${r.type === 'film' ? 'Film' : 'Series'} &middot; ${esc(r.platform)}</span>
                <span><i class="fas fa-calendar"></i> <time datetime="${r.date}" itemprop="datePublished">${formatDate(r.date)}</time></span>
                <span><i class="fas fa-user-edit"></i> Analyzed by <span itemprop="author">Debra Ducane</span></span>
                <span><i class="fas fa-clock"></i> ${esc(r.readTime)} read</span>
              </div>
            </div>
            <div class="featured-poster-wrap" style="flex:0 0 160px;width:160px;height:230px;border-radius:10px;overflow:hidden;border:2px solid rgba(201,168,76,0.3);">
              ${posterHTML(r, 'featured')}
            </div>
          </div>
        </div>

        ${scorePanel(r)}

        <div class="featured-body" id="review-body" itemprop="reviewBody">
          ${spoilerAlertBanner(r)}
          ${wokeTrapAssessment(r)}
          ${creativeTeamSummary(r)}
          <div class="section-label">Overall Perspective</div>
          ${overallParagraphs(r)}
          ${wokeTrapAlert(r)}
          ${tropeTable(r)}
          ${creativeTeamFull(r)}
          ${insightGrid(r)}
          ${whereToWatchBlock(r)}
        </div>
      </article>

      ${relatedReviewsBlock(r)}

      <!-- Comments Section -->
      <div class="comments-section" data-slug="${esc(r.slug)}">
        <div class="comments-header">
          <h3><i class="fas fa-comments"></i> Community Discussion <span id="vv-comment-count" class="comment-count">0</span></h3>
        </div>

        <div id="comment-subscribe-prompt" class="subscribe-prompt">
          <div class="subscribe-prompt-inner">
            <i class="fas fa-lock"></i>
            <div>
              <p><strong>Subscribe to comment.</strong></p>
              <p>Join the VirtueVigil community to share your perspective on this review.</p>
            </div>
            <a href="/subscribe/" class="btn-subscribe-cta">Sign In / Subscribe</a>
          </div>
        </div>

        <div id="comment-form-container" style="display:none;">
          <form id="vv-comment-form" class="comment-form">
            <textarea id="vv-comment-input" placeholder="Share your thoughts on this review..." maxlength="2000" rows="4"></textarea>
            <div class="comment-form-footer">
              <span id="vv-char-count" class="char-count">0 / 2000</span>
              <button type="submit" class="btn-post-comment">Post Comment</button>
            </div>
          </form>
        </div>

        <div id="vv-comments-list" class="comments-list"></div>
      </div>

      <!-- Previous / Next -->
      <div style="display:flex;justify-content:space-between;margin:30px 0;gap:16px;flex-wrap:wrap;">
        ${prev ? `<a href="/reviews/${prev.slug}/" style="color:var(--gold);font-weight:600;font-size:0.9rem;"><i class="fas fa-arrow-left"></i> ${esc(prev.title)}</a>` : '<span></span>'}
        ${next ? `<a href="/reviews/${next.slug}/" style="color:var(--gold);font-weight:600;font-size:0.9rem;">${esc(next.title)} <i class="fas fa-arrow-right"></i></a>` : '<span></span>'}
      </div>
    </main>
  </div>

  ${fullFooter()}
${pageScripts(['/js/comments.js'])}
</body>
</html>`;
}


